window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7d721d2065d52171"]={"versions": [{"id": "FIG-7d721d2065d52171", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm bzw. Schnittstellen-Modellierungsdiagramm im Kontext des AUTOSAR BSW UML Model Modeling Guide. Es illustriert den Entwurf virtueller Schnittstellen (<code>«interface»</code>) zur Kapselung optionaler C-API-Abhängigkeiten eines Basissoftware-Moduls (<code>Dem</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Modul (<code>«module...»</code>):</strong>\n<ul class=\"fig-list\"><li><code>Dem</code> (Diagnostic Event Manager) als aufrufende Komponente.\n</li></ul>\n</li><li><strong>Virtuelle Schnittstellen (<code>«interface»</code>) mit Abhängigkeitsrelationen (<code>«optional»</code> Gestrichelter Pfeil):</strong>\n<ul class=\"fig-list\"><li><code>Dem_Det_Optional</code>: Bündelt die optionale Funktionssignatur <code>::Det_ReportError</code> mit den Parametern <code>Det_ReportError(return, ModuleId, InstanceId, ApiId, ErrorId)</code>.\n</li><li><code>Dem_Dlt_Optional</code>: Bündelt die optionale Funktionssignatur <code>::Dlt_Dem</code> mit den Parametern <code>Dlt_DemTriggerOnEventStatus(EventId, EventStatusByteOld, EventStatusByteNew)</code>.\n</li><li><code>Dem_Fim_Optional</code>: Bündelt die optionalen Funktionssignaturen <code>::FiM_DemInit</code> (<code>FiM_DemInit()</code>) und <code>::FiM_DemTriggerOnEventStatus</code> (<code>FiM_DemTriggerOnEventStatus(EventId, EventStatusByteOld, EventStatusByteNew)</code>).\n</li><li><code>Dem_NvM_Optional</code>: Bündelt die optionalen Funktionssignaturen <code>::NvM_GetErrorStatus</code> (<code>NvM_GetErrorStatus(return, BlockId, RequestResultPtr)</code>), <code>::NvM_SetRamBlockStatus</code> (<code>NvM_SetRamBlockStatus(return, BlockId, BlockChanged)</code>), <code>::NvM_WriteBlock</code> (<code>NvM_WriteBlock(return, BlockId, NvM_SrcPtr)</code>) und <code>::NvM_ReadBlock</code> (<code>NvM_ReadBlock(return, BlockId, NvM_DstPtr)</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Zeitachse. Dargestellt werden gerichtete Abhängigkeiten (<code>«optional»</code>), über die das Modul <code>Dem</code> im Bedarfsfall (z. B. Ereignisstatusänderung, Fehlerprotokollierung oder NVRAM-Zugriffe) die jeweiligen Servicefunktionen der Zielmodule (Det, Dlt, FiM, NvM) synchron aufruft.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient als methodische Modellierungsrichtlinie für BSW-UML-Modelle: Externe Modulschnittstellen, die über Präprozessor-Schalter (<code>#ifdef</code> / Konfiguration) deaktivierbar oder optional sind, werden als separate virtuelle Interfaces modelliert und über <code>«optional»</code>-Abhängigkeiten angebunden, um Entkopplung und modulare Codegenerierung bzw. statische Analysen zu ermöglichen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-644f316db8bdd2cb", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm bzw. Schnittstellen-Modellierungsdiagramm im Kontext des AUTOSAR BSW UML Model Modeling Guide. Es illustriert den Entwurf virtueller Schnittstellen (<code>«interface»</code>) zur Kapselung optionaler C-API-Abhängigkeiten eines Basissoftware-Moduls (<code>Dem</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Modul (<code>«module...»</code>):</strong>\n<ul class=\"fig-list\"><li><code>Dem</code> (Diagnostic Event Manager) als aufrufende Komponente.\n</li></ul>\n</li><li><strong>Virtuelle Schnittstellen (<code>«interface»</code>) mit Abhängigkeitsrelationen (<code>«optional»</code> Gestrichelter Pfeil):</strong>\n<ul class=\"fig-list\"><li><code>Dem_Det_Optional</code>: Bündelt die optionale Funktionssignatur <code>::Det_ReportError</code> mit den Parametern <code>Det_ReportError(return, ModuleId, InstanceId, ApiId, ErrorId)</code>.\n</li><li><code>Dem_Dlt_Optional</code>: Bündelt die optionale Funktionssignatur <code>::Dlt_Dem</code> mit den Parametern <code>Dlt_DemTriggerOnEventStatus(EventId, EventStatusByteOld, EventStatusByteNew)</code>.\n</li><li><code>Dem_Fim_Optional</code>: Bündelt die optionalen Funktionssignaturen <code>::FiM_DemInit</code> (<code>FiM_DemInit()</code>) und <code>::FiM_DemTriggerOnEventStatus</code> (<code>FiM_DemTriggerOnEventStatus(EventId, EventStatusByteOld, EventStatusByteNew)</code>).\n</li><li><code>Dem_NvM_Optional</code>: Bündelt die optionalen Funktionssignaturen <code>::NvM_GetErrorStatus</code> (<code>NvM_GetErrorStatus(return, BlockId, RequestResultPtr)</code>), <code>::NvM_SetRamBlockStatus</code> (<code>NvM_SetRamBlockStatus(return, BlockId, BlockChanged)</code>), <code>::NvM_WriteBlock</code> (<code>NvM_WriteBlock(return, BlockId, NvM_SrcPtr)</code>) und <code>::NvM_ReadBlock</code> (<code>NvM_ReadBlock(return, BlockId, NvM_DstPtr)</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Zeitachse. Dargestellt werden gerichtete Abhängigkeiten (<code>«optional»</code>), über die das Modul <code>Dem</code> im Bedarfsfall (z. B. Ereignisstatusänderung, Fehlerprotokollierung oder NVRAM-Zugriffe) die jeweiligen Servicefunktionen der Zielmodule (Det, Dlt, FiM, NvM) synchron aufruft.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient als methodische Modellierungsrichtlinie für BSW-UML-Modelle: Externe Modulschnittstellen, die über Präprozessor-Schalter (<code>#ifdef</code> / Konfiguration) deaktivierbar oder optional sind, werden als separate virtuelle Interfaces modelliert und über <code>«optional»</code>-Abhängigkeiten angebunden, um Entkopplung und modulare Codegenerierung bzw. statische Analysen zu ermöglichen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-7d721d2065d52171", "to": "FIG-644f316db8bdd2cb", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
